import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { createManifest, verifyManifest } from '../snapshot.js';

const script = fileURLToPath(new URL('../snapshot.js', import.meta.url));
const hash = '0'.repeat(64);

function fixture(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-extension-'));
  t.after(() => fs.rmSync(root, { recursive: true, force: true }));
  return root;
}
function write(root, name, contents, mode = 0o640) {
  const target = path.join(root, name);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, contents);
  fs.chmodSync(target, mode);
}
function entry(overrides = {}) {
  return { path: 'a', sha256: hash, size: 0, mode: 0, ...overrides };
}
function cli(...args) {
  return spawnSync(process.execPath, [script, ...args], { encoding: 'utf8' });
}

test('manifest validation covers shape, fields, paths, and duplicates', t => {
  const root = fixture(t);
  const invalid = [
    null, [], {}, { version: 2, files: [] }, { version: 1, files: null },
    { version: 1, files: [null] }, { version: 1, files: [[]] },
    { version: 1, files: [entry({ path: '' })] },
    { version: 1, files: [entry({ path: '/a' })] },
    { version: 1, files: [entry({ path: 'a//b' })] },
    { version: 1, files: [entry({ path: 'a/../b' })] },
    { version: 1, files: [entry({ path: 'a\\b' })] },
    { version: 1, files: [entry({ sha256: 'A'.repeat(64) })] },
    { version: 1, files: [entry({ sha256: '0'.repeat(63) })] },
    { version: 1, files: [entry({ size: -1 })] },
    { version: 1, files: [entry({ size: 1.5 })] },
    { version: 1, files: [entry({ size: Number.MAX_SAFE_INTEGER + 1 })] },
    { version: 1, files: [entry({ mode: -1 })] },
    { version: 1, files: [entry({ mode: 512 })] },
    { version: 1, files: [entry(), entry()] },
  ];
  for (const manifest of invalid) assert.throws(() => verifyManifest(root, manifest));
});

test('complete manifest validation precedes file inspection and unknown fields are ignored', t => {
  const root = fixture(t);
  write(root, 'a', 'data');
  const original = fs.readFileSync;
  let reads = 0;
  fs.readFileSync = (...args) => { reads++; return original(...args); };
  try {
    assert.throws(() => verifyManifest(root, {
      version: 1, ignored: true,
      files: [entry({ path: 'a' }), entry({ path: 'bad', size: -1 })],
    }));
    assert.equal(reads, 0);
  } finally {
    fs.readFileSync = original;
  }
  const manifest = createManifest(root, ['a']);
  manifest.extra = { ignored: true };
  manifest.files[0].extra = 42;
  assert.equal(verifyManifest(root, manifest).ok, true);
});

test('frozen inputs remain immutable and empty manifests work', t => {
  const root = fixture(t);
  write(root, 'b', 'b'); write(root, 'a', 'a');
  const paths = Object.freeze(['b', 'a']);
  assert.deepEqual(createManifest(root, paths).files.map(x => x.path), ['a', 'b']);
  const manifest = createManifest(root, ['b', 'a']);
  for (const item of manifest.files) Object.freeze(item);
  Object.freeze(manifest.files); Object.freeze(manifest);
  assert.deepEqual(verifyManifest(root, manifest).unchanged, ['a', 'b']);
  assert.deepEqual(createManifest(root, []), { version: 1, files: [] });
  assert.deepEqual(verifyManifest(root, Object.freeze({ version: 1, files: Object.freeze([]) })),
    { ok: true, unchanged: [], changed: [], missing: [], unsafe: [] });
});

test('byte content, size, modes, and every drift class are distinguished', t => {
  const root = fixture(t);
  write(root, 'same', Buffer.from([0, 255, 10]), 0o600);
  write(root, 'content', 'abc', 0o600);
  write(root, 'size', 'long', 0o600);
  write(root, 'mode', 'mode', 0o600);
  write(root, 'both', 'both', 0o600);
  write(root, 'gone', 'gone', 0o600);
  write(root, 'unsafe', 'file', 0o600);
  const manifest = createManifest(root, ['unsafe', 'same', 'size', 'mode', 'gone', 'content', 'both']);
  write(root, 'content', 'xyz', 0o600);
  write(root, 'size', 'x', 0o600);
  fs.chmodSync(path.join(root, 'mode'), 0o644);
