import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

function validateRoot(root) {
  // lstat("link/") follows the link on POSIX, so remove trailing separators
  // before checking the object named by the caller.
  let checked = root;
  if (typeof root === 'string') {
    const parsedRoot = path.parse(root).root;
    while (checked.length > parsedRoot.length && checked.endsWith(path.sep)) checked = checked.slice(0, -1);
  }
  const stat = fs.lstatSync(checked);
  if (!stat.isDirectory() || stat.isSymbolicLink()) throw Error('root must be a non-symlink directory');
}

function validatePath(selected) {
  if (typeof selected !== 'string' || !selected || selected.startsWith('/')
    || selected.includes('\\') || selected.includes('\0')
    || selected.split('/').some(part => !part || part === '.' || part === '..')) {
    throw Error('invalid selected path');
  }
}

function inspect(root, selected) {
  const parts = selected.split('/');
  let current = root;
  for (let i = 0; i < parts.length; i++) {
    current = path.join(current, parts[i]);
    let stat;
    try {
      stat = fs.lstatSync(current);
    } catch (error) {
      if (error.code === 'ENOENT') return { kind: 'missing' };
      throw error;
    }
    const final = i === parts.length - 1;
    if (stat.isSymbolicLink() || (final ? !stat.isFile() : !stat.isDirectory())) {
      return { kind: 'unsafe' };
    }
    if (final) {
      const bytes = fs.readFileSync(current);
      return {
        kind: 'file',
        sha256: crypto.createHash('sha256').update(bytes).digest('hex'),
        size: bytes.length,
        mode: stat.mode & 0o777,
      };
    }
  }
}

function compareStrings(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

export function createManifest(root, paths) {
  validateRoot(root);
  if (!Array.isArray(paths)) throw Error('paths must be an array');
  const seen = new Set();
  for (const selected of paths) {
    validatePath(selected);
    if (seen.has(selected)) throw Error('duplicate selection');
    seen.add(selected);
  }
  return {
    version: 1,
    files: [...paths].sort(compareStrings).map(selected => {
      const current = inspect(root, selected);
      if (current.kind !== 'file') throw Error(`${current.kind} selected path`);
      return { path: selected, sha256: current.sha256, size: current.size, mode: current.mode };
    }),
  };
}

function validateManifest(manifest) {
  if (manifest === null || typeof manifest !== 'object' || Array.isArray(manifest)) {
    throw Error('manifest must be an object');
  }
  if (manifest.version !== 1 || !Array.isArray(manifest.files)) throw Error('invalid manifest');

  const seen = new Set();
  const entries = [];
  for (const entry of manifest.files) {
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) {
      throw Error('manifest file entry must be an object');
    }
    validatePath(entry.path);
    if (seen.has(entry.path)) throw Error('duplicate manifest path');
    seen.add(entry.path);
    if (typeof entry.sha256 !== 'string' || entry.sha256.length !== 64
      || !/^[0-9a-f]{64}$/.test(entry.sha256)) {
      throw Error('invalid sha256');
    }
    if (!Number.isSafeInteger(entry.size) || entry.size < 0) throw Error('invalid size');
    if (!Number.isInteger(entry.mode) || entry.mode < 0 || entry.mode > 0o777) throw Error('invalid mode');
    entries.push({ path: entry.path, sha256: entry.sha256, size: entry.size, mode: entry.mode });
  }
  return entries;
}

export function verifyManifest(root, manifest) {
  // Validate and copy every entry before touching root or any selected path.
  const entries = validateManifest(manifest);
  validateRoot(root);

  const unchanged = [];
  const changed = [];
  const missing = [];
  const unsafe = [];
  for (const entry of entries) {
    const current = inspect(root, entry.path);
    if (current.kind === 'missing') {
      missing.push(entry.path);
    } else if (current.kind === 'unsafe') {
      unsafe.push(entry.path);
    } else {
      const reasons = [];
      if (current.sha256 !== entry.sha256 || current.size !== entry.size) reasons.push('content');
      if (current.mode !== entry.mode) reasons.push('mode');
      if (reasons.length) changed.push({ path: entry.path, reasons });
      else unchanged.push(entry.path);
    }
  }
  unchanged.sort(compareStrings);
  changed.sort((a, b) => compareStrings(a.path, b.path));
  missing.sort(compareStrings);
  unsafe.sort(compareStrings);
  return {
    ok: changed.length === 0 && missing.length === 0 && unsafe.length === 0,
    unchanged,
    changed,
    missing,
    unsafe,
  };
}

function runCli(argv) {
  const [command, ...args] = argv;
  if (command === 'create') {
    if (args.length < 1) throw Error('usage: snapshot.js create ROOT [PATH ...]');
    return { value: createManifest(args[0], args.slice(1)), status: 0 };
  }
  if (command === 'verify') {
    if (args.length !== 2) throw Error('usage: snapshot.js verify ROOT MANIFEST_FILE');
    const manifest = JSON.parse(fs.readFileSync(args[1], 'utf8'));
    const value = verifyManifest(args[0], manifest);
    return { value, status: value.ok ? 0 : 1 };
  }
  throw Error('usage: snapshot.js create ROOT [PATH ...] | verify ROOT MANIFEST_FILE');
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const result = runCli(process.argv.slice(2));
    process.stdout.write(`${JSON.stringify(result.value)}\n`);
    process.exitCode = result.status;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`${message || 'error'}\n`);
    process.exitCode = 2;
  }
}

