import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { createManifest, verifyManifest } from '../snapshot.js';

const script = fileURLToPath(new URL('../snapshot.js', import.meta.url));
const hash = 'a'.repeat(64);

function fixture(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-milestone-'));
  t.after(() => fs.rmSync(root, { recursive: true, force: true }));
  return root;
}

function write(root, name, contents = name) {
  const target = path.join(root, name);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, contents);
}

function manifestEntry(pathname, overrides = {}) {
  return { path: pathname, sha256: hash, size: 0, mode: 0, ...overrides };
}

function cli(...args) {
  return spawnSync(process.execPath, [script, ...args], { encoding: 'utf8' });
}

function assertCliError(result) {
  assert.equal(result.status, 2);
  assert.equal(result.stdout, '');
  assert.notEqual(result.stderr, '');
}

test('sha256 validation requires exactly 64 lowercase hexadecimal characters', t => {
  const root = fixture(t);
  const valid = { version: 1, files: [manifestEntry('absent')] };
  assert.deepEqual(verifyManifest(root, valid).missing, ['absent']);

  for (const terminator of ['\n', '\r', '\r\n', '\u2028', '\u2029']) {
    const invalid = {
      version: 1,
      files: [manifestEntry('absent', { sha256: hash + terminator })],
    };
    assert.throws(() => verifyManifest(root, invalid), /sha256/);
  }
});

test('a correct hash paired with a deliberately wrong size reports content drift', t => {
  const root = fixture(t);
  write(root, 'file', 'unchanged bytes');
  const manifest = createManifest(root, ['file']);
  manifest.files[0].size += 1;
  assert.deepEqual(verifyManifest(root, manifest).changed, [
    { path: 'file', reasons: ['content'] },
  ]);
});

test('intermediate files and internal or dangling symlinks are unsafe', t => {
  const root = fixture(t);
  write(root, 'basis', 'basis');
  write(root, 'middle', 'not a directory');
  write(root, 'inside', 'target');
  fs.symlinkSync('inside', path.join(root, 'internal-link'));
  fs.symlinkSync('does-not-exist', path.join(root, 'dangling-link'));

  const basis = createManifest(root, ['basis']).files[0];
  const verifyPath = pathname => verifyManifest(root, {
    version: 1,
    files: [{ ...basis, path: pathname }],
  });
  assert.deepEqual(verifyPath('middle/child').unsafe, ['middle/child']);
  assert.deepEqual(verifyPath('internal-link').unsafe, ['internal-link']);
  assert.deepEqual(verifyPath('dangling-link').unsafe, ['dangling-link']);
});

test('multiple changed, missing, and unsafe entries are sorted with reversed input', t => {
  const root = fixture(t);
  const names = ['changed-z', 'changed-a', 'missing-z', 'missing-a', 'unsafe-z', 'unsafe-a'];
  for (const name of names) write(root, name, `original ${name}`);
  const manifest = createManifest(root, names);

  write(root, 'changed-z', 'new z');
  write(root, 'changed-a', 'new a');
  fs.rmSync(path.join(root, 'missing-z'));
  fs.rmSync(path.join(root, 'missing-a'));
  for (const name of ['unsafe-z', 'unsafe-a']) {
    fs.rmSync(path.join(root, name));
    fs.mkdirSync(path.join(root, name));
  }
  manifest.files.reverse();

  const report = verifyManifest(root, manifest);
  assert.deepEqual(report.changed, [
    { path: 'changed-a', reasons: ['content'] },
    { path: 'changed-z', reasons: ['content'] },
  ]);
  assert.deepEqual(report.missing, ['missing-a', 'missing-z']);
  assert.deepEqual(report.unsafe, ['unsafe-a', 'unsafe-z']);
});

test('filesystem EACCES is thrown rather than classified as drift', t => {
  const root = fixture(t);
  write(root, 'locked', 'data');
  const manifest = createManifest(root, ['locked']);
  const target = path.join(root, 'locked');
  const original = fs.lstatSync;
  const denied = Object.assign(new Error('permission denied'), { code: 'EACCES' });
  fs.lstatSync = pathname => {
    if (pathname === target) throw denied;
    return original(pathname);
  };
  try {
    assert.throws(() => verifyManifest(root, manifest), error => error === denied);
  } finally {
    fs.lstatSync = original;
  }
});

test('CLI error and empty-create contracts specify status and streams', t => {
  const root = fixture(t);
  const manifestFile = path.join(root, 'manifest.json');

  let result = cli('create', root);
  assert.equal(result.status, 0);
  assert.equal(result.stderr, '');
  assert.equal(result.stdout, '{"version":1,"files":[]}\n');

  fs.writeFileSync(manifestFile, JSON.stringify({ version: 1, files: [manifestEntry('x', { sha256: 'bad' })] }));
  assertCliError(cli('verify', root, manifestFile));
  assertCliError(cli('create', root, '../invalid'));
  assertCliError(cli('create', path.join(root, 'missing-root')));
  assertCliError(cli('verify', root, path.join(root, 'missing-manifest.json')));
});

